cat > LayerDependencyTests.cs <<'E'
using System.Reflection;
using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public class LayerDependencyTests
{
    private static readonly Assembly Domain = typeof(Money).Assembly;
    private static readonly Assembly App = typeof(AuthorizePayment).Assembly;
    private static readonly Assembly Infra = typeof(HttpPaymentGateway).Assembly;

    // Technical details that belong to Infrastructure only.
    private static readonly string[] TechnicalNamespaces =
        ["System.Net.Http", "System.IO", "System.Data", "System.Text.Json", "Microsoft.Data", "Microsoft.EntityFrameworkCore"];

    private static void AssertNoneDepend(Assembly assembly, params string[] forbidden)
    {
        var result = Types.InAssembly(assembly).That().AreNotPublic().Or().ArePublic()
            .ShouldNot().HaveDependencyOnAny(forbidden).GetResult();
        Assert.True(result.IsSuccessful,
            "Forbidden dependency in: " + string.Join(", ", result.FailingTypeNames ?? []));
    }

    [Fact]
    public void Domain_depends_on_no_other_layer() =>
        AssertNoneDepend(Domain, "PaymentAuthorization.Application", "PaymentAuthorization.Infrastructure");

    [Fact]
    public void Domain_uses_no_technical_details() =>
        AssertNoneDepend(Domain, TechnicalNamespaces);

    [Fact]
    public void Application_does_not_depend_on_Infrastructure() =>
        AssertNoneDepend(App, "PaymentAuthorization.Infrastructure");

    [Fact]
    public void Application_uses_no_technical_details() =>
        AssertNoneDepend(App, TechnicalNamespaces);

    [Fact]
    public void Infrastructure_is_not_referenced_by_inner_layers()
    {
        foreach (var assembly in new[] { Domain, App })
            Assert.DoesNotContain(assembly.GetReferencedAssemblies(), a => a.Name == Infra.GetName().Name);
    }
}
